package com.hostelmanagement.service;
import com.hostelmanagement.entity.*; import com.hostelmanagement.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class RoomService { private final RoomRepository rooms; private final StudentRepository students; public RoomService(RoomRepository r,StudentRepository s){rooms=r;students=s;}
 public List<Room> all(){return rooms.findAll();}
 @Transactional public Student allocate(Long studentId,Long roomId){Student s=students.findById(studentId).orElseThrow(); Room r=rooms.findById(roomId).orElseThrow(); if(r.getStatus()==RoomStatus.MAINTENANCE||r.availableBeds()<=0) throw new IllegalStateException("Room unavailable"); if(s.getRoom()!=null) s.getRoom().setOccupiedBeds(Math.max(0,s.getRoom().getOccupiedBeds()-1)); s.setRoom(r); r.setOccupiedBeds(r.getOccupiedBeds()+1); r.setStatus(r.getOccupiedBeds()>=r.getCapacity()?RoomStatus.FULL:RoomStatus.PARTIALLY_OCCUPIED); return s; }
 public List<Map<String,Object>> recommend(Student s){List<Map<String,Object>> out=new ArrayList<>(); for(Room r:rooms.findAll()){if(r.getStatus()==RoomStatus.MAINTENANCE||r.availableBeds()==0)continue; int score=50; if(s.getYear()!=null)score+=10; if("Single".equalsIgnoreCase(r.getRoomType()))score+=5; score=Math.min(score+Math.min(35,r.availableBeds()*10),95); out.add(Map.of("roomId",r.getId(),"roomNumber",r.getRoomNumber(),"compatibility",score+"%","reason","Availability, capacity and configured room preference"));} out.sort((a,b)->String.valueOf(b.get("compatibility")).compareTo(String.valueOf(a.get("compatibility")))); return out; }
}
